/* @lc app=leetcode id=1946 lang=kotlin */
class Solution { fun maximumNumber(num: String, change: IntArray): String = num.fold(StringBuilder() to 0) { (sb, state), ch -> (ch - '0').let { d -> change[d].let { c -> if (state == 0) (if (c > d) ('0' + c) to 1 else ch to 0) else if (state == 1) (if (c >= d) ('0' + c) to 1 else ch to 2) else ch to 2 } }.let { (nextChar, nextState) -> sb.append(nextChar) to nextState } }.first.toString() }